// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _test(uint256 _value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _value + 1 ether);
        vm.assume(_value > 0);
        uint beforeBal = address(this).balance;
        try c.sendMoney(address(this), _value) {} catch { return; }
        assertTrue(address(this).balance == beforeBal + _value);
    }

    function testFuzz_test(uint256 _value) public {
        _test(_value);
    }

    receive() external payable {}
}
